UPDATE KEPASRDT  /*updateApprovalKEPASRDT*/
	   SET RECV_FLAG = #{RECV_FLAG}
	   , REQ_CONFIRM_ID = #{REQ_CONFIRM_ID}
	   , REQ_CONFIRM_DATE = SYSDATE
	 WHERE USER_ID = #{KEY_3} AND SR_NO = #{KEY_1}


UPDATE KEPASRDT  /*updateDataApprovalKEPASRDT*/
	   SET RECV_FLAG = #{RECV_FLAG}
	   , REQ_CONFIRM_ID = #{REQ_CONFIRM_ID}
	   , REQ_CONFIRM_DATE = SYSDATE
	   , CD_DATE = SYSDATE
	   , CD_USER_ID = #{REQ_CONFIRM_ID}
	   , DS_DATE = SYSDATE
	   , DS_USER_ID = #{REQ_CONFIRM_ID}
	   , DP_DATE = SYSDATE
	   , DP_USER_ID = #{REQ_CONFIRM_ID}
	   , DF_DATE = SYSDATE
	   , DF_REMARK ='결재일 기준 3일 이후는 다운로드 불가능 합니다. 유효일:'||TO_CHAR(SYSDATE+3,'YYYY/MM/DD')
	 WHERE USER_ID = #{KEY_3} AND SR_NO = #{KEY_1}
